(function(){
'use strict';
const C=window.JeiOKLCH,root=document.documentElement,dock=document.querySelector('#report-dock'),key='jei-report-v6-oklch';
const host=dock.querySelector('#color-editor'),presets=[['레드','#e5303a'],['코랄','#cf725b'],['앰버','#b78328'],['그린','#328472'],['블루','#5379ae'],['퍼플','#8b64a7']];
host.innerHTML=`<h3>강조 컬러</h3><p>주요 버튼과 AI 심볼의 강조 색만 바뀌어요.</p><div class="color-presets">${presets.map(([name,color])=>`<button type="button" data-palette="${color}" style="--swatch:${color}" aria-label="${name} 컬러" aria-pressed="false" title="${name}"></button>`).join('')}</div><div class="color-entry"><input id="palette-picker" type="color" value="#e5303a" aria-label="기준 색 선택"><input id="palette-hex" type="text" value="#E5303A" maxlength="7" spellcheck="false" aria-label="HEX 색상" placeholder="#E5303A"></div><details><summary>직접 조정 · OKLCH</summary>${[['l','밝기 L',15,90,1],['c','선명도 C',0,0.32,0.005],['h','색상 H',0,360,1]].map(([id,name,min,max,step])=>`<label class="color-slider">${name}<output id="value-${id}"></output><input aria-label="${name}" id="color-${id}" type="range" min="${min}" max="${max}" step="${step}"></label>`).join('')}</details><div class="color-scale" aria-label="강조 요소의 색상 단계"></div><p>AI 심볼 · 주요 버튼 · 버튼 호버</p><p id="palette-status" role="status" aria-live="polite"></p><div class="color-actions"><button type="button" id="palette-reset">컬러 초기화</button></div>`;
const originalColors=window.JeiReportColors;let chosen=null,values=C.lab('#e5303a'),palette=null,frame=0;
function apply(){palette=chosen?C.palette(values):null;
 if(!palette){root.removeAttribute('data-custom-palette');for(const name of ['accent','primary','hover'])root.style.removeProperty('--v6-'+name);}
 else{root.setAttribute('data-custom-palette','true');for(const name of ['accent','primary','hover'])root.style.setProperty('--v6-'+name,palette[name]);}
 sync();try{localStorage.setItem(key,JSON.stringify(chosen?values:null));}catch{}}
function sync(){const p=palette||C.palette(values),hex=C.hex(values.l,values.c,values.h);host.querySelector('#palette-picker').value=hex;host.querySelector('#palette-hex').value=hex.toUpperCase();for(const id of ['l','c','h']){const n=id==='l'?values.l*100:values[id];host.querySelector('#color-'+id).value=n;host.querySelector('#value-'+id).textContent=id==='l'?Math.round(n)+'%':id==='h'?Math.round(n)+'°':n.toFixed(3);}for(const b of host.querySelectorAll('[data-palette]'))b.setAttribute('aria-pressed',String(!!chosen&&b.dataset.palette.toLowerCase()===hex.toLowerCase()));host.querySelector('.color-scale').innerHTML=['accent','primary','hover'].map(k=>`<i style="background:${p[k]}"></i>`).join('');host.querySelector('#palette-status').textContent=palette?'강조 컬러 적용 중 · 버튼 글자 대비 '+C.contrast(p.primary,'#ffffff').toFixed(1)+':1':'기본 보고용 컬러';}
function choose(hex){if(!/^#[\da-f]{6}$/i.test(hex))return false;values=C.lab(hex);chosen=true;apply();return true;}
host.addEventListener('click',e=>{const b=e.target.closest('[data-palette]');if(b)choose(b.dataset.palette);if(e.target.closest('#palette-reset')){chosen=null;values=C.lab('#e5303a');apply();}});
host.querySelector('#palette-picker').addEventListener('input',e=>choose(e.target.value));host.querySelector('#palette-hex').addEventListener('change',e=>{if(!choose(e.target.value)){e.target.setCustomValidity('예: #E5303A 형식으로 입력해주세요.');e.target.reportValidity();}else e.target.setCustomValidity('');});host.querySelector('#palette-hex').addEventListener('input',e=>e.target.setCustomValidity(''));
for(const id of ['l','c','h'])host.querySelector('#color-'+id).addEventListener('input',e=>{values[id]=Number(e.target.value)/(id==='l'?100:1);chosen=true;cancelAnimationFrame(frame);frame=requestAnimationFrame(apply);});
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&['l','c','h'].every(k=>Number.isFinite(saved[k]))){values=saved;chosen=true;}}catch{}apply();
})();
